import {MAPS,AGENTS,initialState,demoState,applyCommand,standings,metrics,matchSide,currentVeto,eligibleForFinal,parseScoreboard,https,activePlayers} from './lib/kov-core.mjs';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=$('#kov-app');
const readLocal=k=>{try{return localStorage.getItem(k);}catch{return null;}};
async function responseJson(response){const body=await response.text();try{return JSON.parse(body);}catch{throw Error('대회 서버가 정상적으로 응답하지 않았습니다. 잠시 후 새로고침해 주세요.');}}
const writeLocal=(k,v)=>{try{localStorage.setItem(k,v);return true;}catch{return false;}};
let state=initialState(),actor=null,demo=new URLSearchParams(location.search).get('demo')==='1'||readLocal('kov-demo-active')==='1',storageReady=false,webhookReady=false,loading=true,busy=false,detailTab='overview';
let route=location.hash.startsWith('#kov/')?location.hash.slice(5).split('/').map(decodeURIComponent):['tournaments'];
let selectedTeam='',resultDraft=null,recordFilters={},recordTab='players',adminTournament='',toastTimer,ocrBusy=false;
const names={draft:'준비 중',registration:'참가 모집',ongoing:'진행 중',finished:'종료',pending:'승인 대기',approved:'승인 완료',rejected:'반려',scheduled:'경기 예정',waiting:'대진 대기',veto:'밴픽 중',playing:'경기 진행',review:'결과 검수',cancelled:'미진행',confirmed:'확정',sent:'전송 완료',failed:'전송 실패',sending:'전송 중'};
const date=(v,short=false)=>v?new Date(v).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',year:short?undefined:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})+' KST':'일정 미정';
const badge=(value)=>`<span class="kp-badge ${['veto','playing','review'].includes(value)?'red':['approved','confirmed','finished','sent'].includes(value)?'green':value==='registration'?'blue':''}">${esc(names[value]||value)}</span>`;
const button=(label,action,data='',style='')=>`<button class="kp-button ${style}" type="button" data-action="${action}" ${data}>${label}</button>`;
const go=(label,path,style='')=>button(label,'route',`data-path="${esc(path)}"`,style);
const external=(label,url)=>https(url)?`<a class="kp-button" href="${esc(https(url))}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:'';
const empty=(title,body,action='')=>`<div class="kp-panel kp-empty"><strong>${esc(title)}</strong><span>${esc(body)}</span>${action}</div>`;
const section=(n,title,body,action='')=>`<section class="kp-section"><div class="kp-section-head"><h2><span class="kp-number">${n}</span>${esc(title)}</h2>${action}</div>${body}</section>`;
const teamName=id=>state.teams.find(t=>t.id===id)?.name||state.applications.find(a=>a.teamId===id)?.snapshot.name||'TBD';
const logo=(roster)=>https(roster?.logoUrl)?`<img class="kp-logo" src="${esc(https(roster.logoUrl))}" alt="${esc(roster.name)} 로고">`:`<span class="kp-logo" aria-hidden="true">${esc((roster?.name||'?').slice(0,1))}</span>`;
const mapImage=name=>MAPS.find(m=>m.name===name)?.image||'';
const tour=id=>state.tournaments.find(t=>t.id===id);
const match=id=>state.matches.find(m=>m.id===id);
const admin=()=>!!actor?.isAdmin;
const myTeams=()=>state.teams.filter(t=>t.captainId===actor?.id);
const mySide=m=>matchSide(m,actor);
const toast=message=>{let el=$('#kp-toast');if(!el){el=document.createElement('div');el.id='kp-toast';el.className='kp-toast';el.setAttribute('role','status');document.body.appendChild(el);}el.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),6500);};

const modal=document.createElement('dialog');modal.id='kp-modal';modal.setAttribute('aria-labelledby','kp-modal-title');document.body.appendChild(modal);
function showModal(title,body){modal.innerHTML=`<div class="kp-modal-head"><h2 id="kp-modal-title">${esc(title)}</h2><button type="button" class="kp-modal-close" data-action="close-modal" aria-label="닫기">×</button></div><div class="kp-modal-body">${body}</div>`;if(!modal.open)modal.showModal();}
modal.addEventListener('click',e=>{const r=modal.getBoundingClientRect();if(e.target===modal&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))modal.close();});

function roleOptions(){return `<option value="demo-admin" ${actor?.id==='demo-admin'?'selected':''}>운영진 체험</option>${state.teams.slice(0,2).map((t,i)=>`<option value="demo-captain-${i}" ${actor?.id===`demo-captain-${i}`?'selected':''}>${esc(t.name)} 주장</option>`).join('')}<option value="demo-viewer" ${actor?.id==='demo-viewer'?'selected':''}>일반 관람자</option>`;}
function statusBar(){return `<div class="kp-statusbar ${demo?'demo':''}"><span class="kp-mode">${demo?'DEMO / 체험 모드':'KOV / LIVE SERVICE'}</span><span>${demo?'예시 데이터 · 이 브라우저에만 저장됩니다.':loading?'서버 연결 중…':!storageReady?'저장소 연결 대기 · 운영 데이터 미등록':'대회 서버 연결됨'}</span><div class="kp-right">${demo?`<label class="kp-inline-label">역할<select id="kp-demo-role" aria-label="체험 역할">${roleOptions()}</select></label>${button('초기화','reset-demo','','small')}${button('실서비스로','exit-demo','','small')}`:`<span>${actor?`${esc(actor.name)} · ${actor.isAdmin?'운영진':'선수'} · ID ${esc(actor.id)}`:'게스트'}</span>${actor?'':button('Discord 로그인','login','','small')}${button('전체 기능 체험','enter-demo','','small')}`}</div></div>`;}
function routeNav(){const tid=route[0]==='tournament'||route[0]==='apply'||route[0]==='bracket'?route[1]:match(route[1])?.tournamentId||state.tournaments[0]?.id;const m=state.matches.find(x=>x.tournamentId===tid&&!['waiting','cancelled','finished'].includes(x.status))||state.matches.find(x=>x.tournamentId===tid);const items=[['① 대회 메인','tournaments'],['② 대회 상세',tid?`tournament/${tid}`:'tournaments'],['③ 참가 신청',tid?`apply/${tid}`:'tournaments'],['④ 대진표',tid?`bracket/${tid}`:'tournaments'],['⑤ 경기',m?`match/${m.id}`:'tournaments'],['⑥ 밴픽',m?`veto/${m.id}`:'tournaments'],['⑦ 결과 등록',m?`result/${m.id}`:'tournaments'],['⑧ 기록실','records'],['⑨ 관리실','admin']];return `<nav class="kp-route-nav" aria-label="대회 화면">${items.map(([l,p])=>`<button data-action="route" data-path="${esc(p)}" class="${route[0]===p.split('/')[0]?'current':''}">${l}</button>`).join('')}</nav>`;}
function top(eyebrow,title,desc,actions='',back=''){return `<div class="kp-top"><div>${back?`<button class="kp-back" data-action="route" data-path="${esc(back)}">← 이전 화면</button><br>`:''}<span class="kp-eyebrow">${eyebrow}</span><h1 class="kp-title">${esc(title)}</h1><p class="kp-desc">${esc(desc)}</p></div><div class="kp-top-actions">${actions}</div></div>`;}
function matchCard(m){return `<button class="kp-panel kp-match" data-action="route" data-path="match/${esc(m.id)}"><div class="kp-match-top">${badge(m.status)}<span>${esc(m.stage==='swiss'?`SWISS R${m.round} · ${m.group}`:m.slot)} · BO${m.bestOf}</span></div><div class="kp-match-teams"><div class="kp-team">${logo(m.rosterA)}<span class="kp-team-name">${esc(m.rosterA?.name||'TBD')}</span></div><strong class="kp-score">${m.status==='finished'||m.scoreA||m.scoreB?`${m.scoreA}<i>:</i>${m.scoreB}`:'VS'}</strong><div class="kp-team">${logo(m.rosterB)}<span class="kp-team-name">${esc(m.rosterB?.name||(m.bye?'부전승':'TBD'))}</span></div></div><div class="kp-match-foot"><span>${date(m.startsAt,true)}</span><span>경기 보기 ↗</span></div></button>`;}
function listMatches(ms){return ms.length?`<div class="kp-grid three">${ms.map(matchCard).join('')}</div>`:empty('등록된 경기가 없습니다.','운영진이 대진을 생성하면 경기 일정이 표시됩니다.');}
function tournamentMain(){
  const sorted=state.tournaments.slice().sort((a,b)=>Date.parse(b.startAt)-Date.parse(a.startAt));const featured=sorted.find(t=>t.status==='ongoing')||sorted.find(t=>t.status==='registration')||sorted[0];
  const active=state.matches.filter(m=>!['waiting','cancelled','finished'].includes(m.status)).sort((a,b)=>Date.parse(a.startsAt)-Date.parse(b.startsAt));
  const finished=state.matches.filter(m=>m.status==='finished'&&!m.bye).slice().reverse().slice(0,3);
  const hero=`<section class="kp-hero"><div class="kp-hero-copy"><span class="kp-eyebrow">${featured?esc(featured.season)+' / '+esc(names[featured.status]):'KOV OFFICIAL TOURNAMENT'}</span><h1>${featured?esc(featured.name):'승리를 향한<br>다음 무대, <span>KOV.</span>'}</h1><p class="kp-desc">${esc(featured?.description||'팀을 만나고, 실력을 증명하고, 새로운 정상에 도전하세요. 다음 KOV 대회를 준비하고 있습니다.')}</p><div class="kp-hero-meta"><span>대회 일정<strong>${featured?date(featured.startAt,true):'추후 공개'}</strong></span><span>상금<strong>${esc(featured?.prize||'추후 공개')}</strong></span><span>참가 규모<strong>${featured?`${state.applications.filter(a=>a.tournamentId===featured.id&&a.status==='approved').length} / ${featured.capacity} TEAMS`:'안내 예정'}</strong></span></div><div class="kp-actions">${featured?go('대회 보기 ↗',`tournament/${featured.id}`,'primary')+go('참가 신청 →',`apply/${featured.id}`):button('전체 기능 체험 ↗','enter-demo','','primary')}</div></div><div class="kp-hero-art"><small>KOV COMPETITIVE COMMUNITY <span>VALORANT</span></small><div class="kp-art-title">PLAY.<br>COMPETE.<br><span>PROVE.</span></div><small>ONE TEAM. NEXT LEVEL.<span>${featured?esc(featured.kind):'COMING SOON'}</span></small>${https(featured?.posterUrl)?`<img src="${esc(https(featured.posterUrl))}" alt="${esc(featured.name)} 포스터">`:''}</div></section>`;
  return hero+section('01','다음 경기',listMatches(active.slice(0,3)),featured?go('전체 대진표 ↗',`bracket/${featured.id}`,'small'):'')+section('02','KOV TOURNAMENTS',sorted.length?`<div class="kp-grid three">${sorted.map(t=>`<article class="kp-panel kp-tournament-card">${badge(t.status)}<span class="kp-eyebrow">${esc(t.season)}</span><h3>${esc(t.name)}</h3><span class="kp-meta">${date(t.startAt,true)} · ${t.capacity} TEAMS</span><div class="kp-actions">${go('상세 보기 ↗',`tournament/${t.id}`,'small')}${t.status==='registration'?go('참가 신청',`apply/${t.id}`,'small'):''}</div></article>`).join('')}</div>`:empty('공식 대회를 준비하고 있습니다.','운영진이 대회를 등록하면 이곳에서 참가할 수 있습니다.',admin()?button('대회 등록','new-tournament','','primary'):''))+section('03','최신 경기 결과',listMatches(finished),go('선수·팀 기록실 ↗','records','small'))+section('04','후원·파트너',`<div class="kp-partners"><div><span class="kp-eyebrow">BETTER TOGETHER</span><br><strong>함께 만드는 더 큰 무대</strong></div><span>공식 후원·파트너 라인업을 준비하고 있습니다.</span></div>`);
}
function rosterTable(r){return `<div class="kp-table-scroll"><table class="kp-roster-table"><thead><tr><th>구분</th><th>선수</th><th>Riot ID · 참가 당시 명단</th></tr></thead><tbody>${(r?.players||[]).map(p=>`<tr><td>${p.slot==='sub'?'후보':'주전'} ${p.discordId&&p.discordId===r.captainId?'ⓒ':''}</td><td>${esc(p.name)}</td><td>${esc(p.riotId)}</td></tr>`).join('')}</tbody></table></div>`;}
function tournamentDetail(tid){const t=tour(tid);if(!t)return notFound();const apps=state.applications.filter(a=>a.tournamentId===tid&&a.status==='approved');const ms=state.matches.filter(m=>m.tournamentId===tid);return top(t.season,t.name,'대회 소개부터 경기와 선수 기록까지, 하나의 무대에서 확인하세요.',badge(t.status)+go('참가 신청 ↗',`apply/${tid}`,'primary')+external('방송 보기',t.broadcastUrl),'tournaments')+`<div class="kp-tabs" role="tablist" aria-label="대회 상세 탭">${[['overview','대회 소개'],['bracket','대진표'],['matches','경기'],['stats','선수 기록']].map(([id,label])=>`<button role="tab" aria-selected="${detailTab===id}" class="${detailTab===id?'active':''}" data-action="detail-tab" data-tab="${id}">${label}</button>`).join('')}</div>`+(detailTab==='bracket'?bracketBody(tid):detailTab==='matches'?listMatches(ms):detailTab==='stats'?recordsBody({tournamentId:tid}):`<div class="kp-grid two"><article class="kp-panel kp-pad"><h2>대회 소개</h2><p class="kp-desc" style="margin:14px 0 23px">${esc(t.description)}</p><dl class="kp-info-grid"><div><dt>총 상금</dt><dd>${esc(t.prize)}</dd></div><div><dt>진행 방식</dt><dd>스위스 → 4강 더블 엘리미네이션</dd></div><div><dt>대회 일정</dt><dd>${date(t.startAt)}<br>~ ${date(t.endAt)}</dd></div><div><dt>참가 마감</dt><dd>${date(t.deadline)}</dd></div><div><dt>매치 형식</dt><dd>BO${t.bestOf} · 그랜드 파이널 BO5</dd></div><div><dt>시드권</dt><dd>${t.kind==='FINAL'?'WINTER·SUMMER 입상 팀 참가':'상위 '+t.seedSlots+'팀 FINAL 자격'}</dd></div></dl><div class="kp-divider"></div><h3>참가 규정</h3><p class="kp-rules">${esc(t.rules)}</p></article><article class="kp-panel"><div class="kp-card-head"><h3>참가 팀</h3><span class="kp-meta">${apps.length} / ${t.capacity} TEAMS</span></div>${apps.length?apps.map(a=>`<div class="kp-list-row"><div class="kp-team-line">${logo(a.snapshot)}<div><strong>${esc(a.snapshot.name)}</strong><br><small>SEED ${a.seed} · ${a.snapshot.players.length}인 등록</small></div></div>${button('명단 보기','roster',`data-id="${esc(a.id)}"`,'small')}</div>`).join(''):empty('아직 승인된 팀이 없습니다.','참가 신청 후 운영진 승인 시 표시됩니다.')}</article></div>`);}
function applicationPage(tid){const t=tour(tid);if(!t)return notFound();const teams=myTeams();const selected=teams.find(x=>x.id===selectedTeam)||teams[0];selectedTeam=selected?.id||'';const a=state.applications.find(a=>a.tournamentId===tid&&a.teamId===selected?.id&&a.status!=='rejected');return top('TEAM REGISTRATION',`${t.name} 참가 신청`,'기존 팀 명단을 불러오고, 참가 당시 명단을 확정해 운영진 승인을 요청하세요.',button('팀 등록·수정','edit-team',selected?`data-id="${selected.id}"`:'','primary'),`tournament/${tid}`)+(!actor?loginRequired():`<div class="kp-grid two"><article class="kp-panel kp-pad"><div class="kp-form"><label class="kp-field">기존 팀 명단 불러오기<select id="kp-application-team">${teams.length?teams.map(team=>`<option value="${team.id}" ${team.id===selectedTeam?'selected':''}>${esc(team.name)}</option>`).join(''):'<option value="">먼저 팀을 등록해 주세요</option>'}</select></label><div class="kp-note">신청 시점의 팀 로고·주장·주전·후보·Riot ID를 별도 보관합니다. 이후 팀 정보가 바뀌어도 대회 참가 명단과 과거 기록은 유지됩니다.</div>${selected?`<div class="kp-team-line">${logo(selected)}<div><strong>${esc(selected.name)}</strong><br><small>주장 ${esc(selected.captainName)} · ${selected.players.length}명</small></div></div>${rosterTable(selected)}<label class="kp-check"><input type="checkbox" id="kp-roster-consent">명단과 대회 규정을 확인했습니다.</label>${button('명단 확정 후 참가 신청','apply',`data-tid="${tid}" data-team="${selected.id}" ${a?'disabled':''}`,'primary')}`:empty('등록된 팀이 없습니다.','팀을 등록하고 주전 5명의 Riot ID를 입력해 주세요.',button('내 팀 등록','edit-team','','primary'))}</div></article><article class="kp-panel kp-pad"><h2>신청 상태</h2><div class="kp-divider"></div>${a?`${badge(a.status)}<h3 style="margin:16px 0">${esc(a.snapshot.name)}</h3><p class="kp-meta">신청일 ${date(a.submittedAt)}</p><p class="kp-rules">${esc(a.note||'운영진이 참가 명단과 자격을 확인합니다.')}</p>`:empty('아직 신청하지 않았습니다.','왼쪽에서 팀 명단을 확인하고 신청해 주세요.')}<div class="kp-divider"></div><dl class="kp-info-grid"><div><dt>접수 마감</dt><dd>${date(t.deadline)}</dd></div><div><dt>참가 자격</dt><dd>${selected&&eligibleForFinal(state,t,selected.id)?'참가 자격 충족':t.kind==='FINAL'?'시드권 보유 팀만 신청 가능':'5인 팀'}</dd></div></dl><p class="kp-meta" style="margin-top:20px">반려 사유가 있으면 명단을 수정한 뒤 다시 신청할 수 있습니다.</p></article></div>`);}
function bracketCard(m){return `<button class="kp-bracket-card" data-action="route" data-path="match/${m.id}"><div class="kp-match-top"><span>${esc(m.slot||`R${m.round}`)} · BO${m.bestOf}</span>${badge(m.status)}</div>${[['A',m.rosterA,m.teamA],['B',m.rosterB,m.teamB]].map(([side,r,id])=>`<div class="kp-bracket-team ${id&&m.winnerId===id?'winner':''}"><span>${esc(r?.name||(m.bye&&side==='B'?'부전승':'TBD'))}</span><strong>${side==='A'?m.scoreA:m.scoreB}</strong></div>`).join('')}<div class="kp-meta">${date(m.startsAt,true)}</div></button>`;}
function bracketBody(tid){const t=tour(tid),table=standings(state,tid),ms=state.matches.filter(m=>m.tournamentId===tid),swiss=ms.filter(m=>m.stage==='swiss'),playoffs=ms.filter(m=>m.stage!=='swiss');const groups=[...new Set(table.map(r=>`${r.wins}-${r.losses}`))];return section('01','스위스 스테이지',`<div class="kp-note">3승·3패까지 스위스 진행 → 상위 4팀 플레이오프 / 순위: 승수·패수·상대 승수(BH)·시드 / 같은 승패 그룹 우선 매칭 / 재대결 방지 / 홀수 그룹은 플로트, 홀수 참가 팀은 중복 없는 부전승 적용</div><div class="kp-swiss-groups" style="margin-top:16px">${groups.map(group=>`<article class="kp-panel kp-swiss-group"><h3 class="kp-group-title">${group} GROUP ${group.startsWith('3-')?'<span class="kp-badge green">스위스 통과</span>':group.endsWith('-3')?'<span class="kp-badge red">탈락</span>':''}</h3><div class="kp-standings">${table.filter(r=>`${r.wins}-${r.losses}`===group).map(r=>`<div class="kp-standing"><span>${esc(r.name)}</span><span>BH ${r.buchholz} · SEED ${r.seed}</span></div>`).join('')}</div></article>`).join('')||empty('참가 승인 대기','팀이 승인되면 승패 그룹이 표시됩니다.')}</div>`,admin()?button('다음 라운드 생성','generate-swiss',`data-tid="${tid}"`,'small'):'')+section('02','스위스 경기',listMatches(swiss))+section('03','플레이오프 · DOUBLE ELIMINATION',playoffs.length?`<div class="kp-bracket">${[['상위조',['U1','U2','U3']],['하위조',['L1','L2']],['그랜드 파이널',['G1','G2']]].map(([label,slots])=>`<div class="kp-bracket-col"><h3>${label}</h3>${slots.map(slot=>playoffs.find(m=>m.slot===slot)).filter(Boolean).map(bracketCard).join('')}</div>`).join('')}</div><p class="kp-meta">하위조 팀이 그랜드 파이널 1차전에서 승리하면 리셋 결승(G2)을 진행합니다.</p>`:empty('플레이오프 진출 팀을 기다립니다.','스위스 일정을 완료한 후 통과 팀 중 상위 4팀으로 편성합니다.'),admin()?button('플레이오프 생성','generate-playoffs',`data-tid="${tid}"`,'small'):'');}
function bracketPage(tid){const t=tour(tid);return t?top('TOURNAMENT BRACKET',t.name,'승패 그룹부터 상·하위조, 그랜드 파이널까지.',go('대회 상세',`tournament/${tid}`),`tournament/${tid}`)+bracketBody(tid):notFound();}
function matchPage(mid){const m=match(mid);if(!m)return notFound();const t=tour(m.tournamentId),side=mySide(m);const current=m.maps.filter(x=>x.result).length;return top(t?.season||'MATCH CENTER',`${m.rosterA?.name||'TBD'} vs ${m.rosterB?.name||'TBD'}`,`${m.stage==='swiss'?`스위스 R${m.round} · ${m.group}`:m.slot} · BO${m.bestOf}`,external('방송 보기',m.broadcastUrl||t?.broadcastUrl),`tournament/${m.tournamentId}`)+`<section class="kp-panel kp-match-hero"><div class="kp-match-top">${badge(m.status)}<span>${date(m.startsAt)}</span></div><div class="kp-match-teams"><div class="kp-team">${logo(m.rosterA)}<div class="kp-team-name">${esc(m.rosterA?.name||'TBD')}</div><div class="kp-ready"><span class="${m.checkin.A?'done':''}">● 체크인 ${m.checkin.A?'완료':'대기'}</span><span class="${m.ready.A?'done':''}">● 준비 ${m.ready.A?'완료':'대기'}</span></div></div><strong class="kp-score">${m.scoreA}<i>:</i>${m.scoreB}</strong><div class="kp-team">${logo(m.rosterB)}<div class="kp-team-name">${esc(m.rosterB?.name||'TBD')}</div><div class="kp-ready"><span class="${m.checkin.B?'done':''}">● 체크인 ${m.checkin.B?'완료':'대기'}</span><span class="${m.ready.B?'done':''}">● 준비 ${m.ready.B?'완료':'대기'}</span></div></div></div><div class="kp-match-foot"><span>${side?`${side}팀 주장으로 로그인했습니다.`:'체크인·밴픽·결과 제출은 각 팀 주장만 가능합니다.'}</span><span>${m.winnerId?'WINNER · '+esc(m.winnerId===m.teamA?m.rosterA.name:m.rosterB?.name||'부전승'):m.maps.length+' MAPS'}</span></div></section><div class="kp-actions" style="margin:18px 0">${side&&m.status==='scheduled'?button(m.checkin[side]?'체크인 완료':'체크인','checkin',`data-mid="${mid}" ${m.checkin[side]?'disabled':''}`)+button(m.ready[side]?'준비 취소':'경기 준비 완료','ready',`data-mid="${mid}"`):''}${side&&m.status==='scheduled'?button('출전 명단 선택','lineup',`data-mid="${mid}"`):''}${go(m.status==='veto'?'밴픽 진행 보기':'밴픽 입장',`veto/${mid}`,'primary')}${go('결과 제출·검수',`result/${mid}`)}${admin()?button('일정·방송 수정','schedule',`data-mid="${mid}"`):''}</div>${section('01','선택된 맵 · 세트 결과',m.maps.length?`<div class="kp-map-strip">${m.maps.map((map,i)=>`<article class="kp-map-thumb"><img src="${mapImage(map.name)}" alt="${esc(map.name)} 맵"><div><small>SET ${i+1} · ${esc(map.pickedBy)} PICK</small><br><strong>${esc(map.name)}</strong><p class="kp-meta">${map.startSide?`${map.startSide.team}팀 ${map.startSide.side==='attack'?'공격':'수비'} 시작`:'공수 선택 대기'}</p></div><span>${map.result?`${map.result.roundA}:${map.result.roundB}`:m.status==='playing'&&i===current?'NEXT':'—'}</span></article>`).join('')}</div>`:empty('맵 밴픽 대기 중','양 팀이 체크인과 준비를 완료하면 밴픽을 시작할 수 있습니다.'))}${section('02','대회 참가 당시 명단',`<div class="kp-grid two"><article class="kp-panel"><div class="kp-card-head"><h3>${esc(m.rosterA?.name||'TBD')}</h3><span class="kp-meta">TEAM A</span></div>${rosterTable(m.rosterA)}</article><article class="kp-panel"><div class="kp-card-head"><h3>${esc(m.rosterB?.name||'TBD')}</h3><span class="kp-meta">TEAM B</span></div>${rosterTable(m.rosterB)}</article></div>`)}`;}
function vetoPage(mid){const m=match(mid);if(!m)return notFound();const step=currentVeto(m),side=mySide(m);const can=side&&step?.side===side&&m.status==='veto';const history=m.veto?.history||[];return top('LIVE MAP VETO',`${m.rosterA?.name||'TBD'} vs ${m.rosterB?.name||'TBD'}`,'양 팀 주장이 순서대로 밴·픽·공수를 선택합니다. 서버에서 차례와 권한을 검증합니다.',go('경기 페이지',`match/${mid}`),`match/${mid}`)+(!m.veto?`<div class="kp-panel kp-pad"><h2>밴픽 시작 전</h2><p class="kp-desc" style="margin:12px 0 20px">양 팀 체크인과 경기 준비 완료 후 입장할 수 있습니다. 선택 제한 시간은 매 차례 60초입니다.</p>${side?button('밴픽 시작','start-veto',`data-mid="${mid}" ${m.ready.A&&m.ready.B?'':'disabled'}`,'primary'):badge('주장 전용')} ${go('체크인·준비 확인',`match/${mid}`)}</div>`:`<div class="kp-veto-layout">${vetoTeam(m,'A',step?.side)}<div class="kp-veto-center"><div class="kp-turn"><div><span class="kp-eyebrow">${m.veto.complete?'VETO COMPLETE':'CURRENT TURN'}</span><br><strong>${m.veto.complete?'모든 맵과 시작 진영이 확정되었습니다.':`${esc(step.side==='A'?m.rosterA.name:m.rosterB.name)} · ${step.kind==='ban'?'맵 밴':step.kind==='pick'?'맵 픽':'공격 / 수비 선택'}`}</strong></div><span class="kp-countdown" data-deadline="${m.veto.deadline||0}">${m.veto.complete?'✓':'60s'}</span></div>${m.veto.complete?go('경기 시작 · 맵 확인 →',`match/${mid}`,'primary'):step.kind==='side'?`<div class="kp-panel kp-side-select">${button('공격 시작','veto',`data-mid="${mid}" data-value="attack" ${can?'':'disabled'}`,'primary')}${button('수비 시작','veto',`data-mid="${mid}" data-value="defense" ${can?'':'disabled'}`)}</div>`:`<div class="kp-veto-maps">${m.pool.map(name=>{const prior=history.find(h=>h.value===name);return `<button class="kp-map-card ${prior?.kind==='ban'?'banned':prior?.kind==='pick'?'picked':''}" data-action="veto" data-mid="${mid}" data-value="${esc(name)}" ${can&&!prior?'':'disabled'}><img src="${mapImage(name)}" alt=""><strong>${esc(name)}</strong><small>${prior?`${prior.side} ${prior.kind.toUpperCase()}`:can?'선택하기 ↗':'상대 차례 대기'}</small></button>`;}).join('')}</div>`}<div class="kp-actions" style="margin-top:15px">${!m.veto.complete&&side?button('시간 초과 처리','veto-timeout',`data-mid="${mid}"`,'small'):''}<span class="kp-meta">${side?`현재 ${side}팀 주장`:'관람 모드 · 주장만 선택할 수 있습니다.'}</span></div></div>${vetoTeam(m,'B',step?.side)}</div>`)+section('01','밴픽 이력',`<div class="kp-panel kp-veto-history">${history.length?history.map((h,i)=>`<span>${i+1}. ${h.side}팀 · ${h.kind.toUpperCase()} · ${esc(h.value==='attack'?'공격':h.value==='defense'?'수비':h.value)}${h.timeout?' (시간 초과)':''}</span>`).join(''):'<span>선택 이력이 없습니다.</span>'}</div>`);}
function vetoTeam(m,side,active){const r=side==='A'?m.rosterA:m.rosterB;return `<article class="kp-panel kp-veto-team ${active===side?'active':''}">${logo(r)}<div><strong>${esc(r?.name||'TBD')}</strong><small>TEAM ${side} · ${esc(r?.captainName||'주장 대기')}</small></div>${mySide(m)===side?'<span class="kp-badge red">MY TEAM</span>':''}</article>`;}
function defaultDraft(m){const players=[...activePlayers(m,'A').map(p=>({...p,teamId:m.teamA})),...activePlayers(m,'B').map(p=>({...p,teamId:m.teamB}))];return {matchId:m.id,mapIndex:m.maps.filter(x=>x.result).length,image:'',raw:'',roundA:'',roundB:'',rows:players.map(p=>({...p,kills:'',deaths:'',assists:'',agent:'기타',confidence:0,reviewed:false})),progress:''};}
function resultPage(mid){const m=match(mid);if(!m)return notFound();const submissions=state.submissions.filter(s=>s.matchId===mid);const pending=submissions.find(s=>s.status==='pending');if(pending&&admin())return reviewPage(m,pending);
  const base=top('RESULT SUBMISSION',`${m.rosterA?.name||'TBD'} vs ${m.rosterB?.name||'TBD'}`,'결과 이미지에서 기록을 추출한 뒤 모든 칸을 확인해 주세요. 운영진 확정 후에만 공식 기록에 반영됩니다.','',`match/${mid}`);
  if(pending)return base+empty('운영진이 결과를 검수 중입니다.',`${pending.map} · ${pending.roundA} : ${pending.roundB} / 확정 전에는 순위와 선수 기록에 반영되지 않습니다.`,go('경기로 돌아가기',`match/${mid}`));
  if(!mySide(m)||!['playing','review'].includes(m.status))return base+empty(m.status==='finished'?'경기가 종료되었습니다.':'결과를 제출할 수 없습니다.','밴픽이 완료된 경기의 주장만 결과를 제출할 수 있습니다.',go('경기·밴픽 확인',`match/${mid}`))+confirmedResults(submissions);
  if(!resultDraft||resultDraft.matchId!==mid||resultDraft.mapIndex!==m.maps.filter(x=>x.result).length)resultDraft=defaultDraft(m);
  const d=resultDraft;const map=m.maps[d.mapIndex];return base+`<div class="kp-note" style="margin-bottom:18px">노란색 칸은 인식 신뢰도가 낮거나 아직 확인되지 않은 항목입니다. OCR은 이름과 K / D / A 형식을 보수적으로 추출합니다. 인식하지 못한 값은 직접 입력하고, 선수별 확인 체크를 해 주세요.</div><form id="kp-result-form" class="kp-result-layout"><article class="kp-panel kp-pad"><span class="kp-eyebrow">SET ${d.mapIndex+1} / ${esc(map.name)}</span><h3 style="margin:10px 0">결과 스크린샷</h3>${d.image?`<img class="kp-evidence" src="${d.image}" alt="업로드한 경기 결과 스크린샷">`:''}<label class="kp-upload"><span>＋</span><strong>${d.image?'스크린샷 바꾸기':'결과 이미지를 선택하세요'}</strong><small>PNG · JPEG · WebP / 최대 8MB 입력<br>업로드 전 브라우저에서 이미지 크기를 줄입니다.</small><input type="file" id="kp-result-image" accept="image/png,image/jpeg,image/webp" aria-label="결과 스크린샷 선택"></label><div class="kp-actions" style="margin-top:15px">${button(ocrBusy?'인식 중…':'이미지에서 기록 추출','ocr',`${!d.image||ocrBusy?'disabled':''}`,'primary small')}</div><div class="kp-progress" id="kp-ocr-progress">${esc(d.progress)}</div><details><summary class="kp-meta">OCR 원문 보기 · 직접 붙여넣기</summary><textarea id="kp-ocr-text" class="kp-ocr-raw" aria-label="OCR 원문">${esc(d.raw)}</textarea>${button('원문에서 다시 추출','parse-ocr','','small')}</details></article><article class="kp-panel kp-pad"><div class="kp-section-head"><h2>SET ${d.mapIndex+1} · 선수별 기록</h2><span class="kp-meta">${esc(map.name)}</span></div><label class="kp-field">라운드 스코어 · ${esc(m.rosterA.name)} : ${esc(m.rosterB.name)}</label><div class="kp-score-edit"><input aria-label="A팀 라운드 스코어" name="roundA" type="number" min="0" max="60" required value="${esc(d.roundA)}"><span>:</span><input aria-label="B팀 라운드 스코어" name="roundB" type="number" min="0" max="60" required value="${esc(d.roundB)}"></div><div class="kp-table-scroll"><table class="kp-roster-table"><thead><tr><th>팀 / Riot ID</th><th>요원</th><th>K</th><th>D</th><th>A</th><th>확인</th></tr></thead><tbody>${d.rows.map((r,i)=>`<tr data-player-row="${i}"><td><span class="kp-meta">${esc(r.teamId===m.teamA?m.rosterA.name:m.rosterB.name)}</span><br><span class="kp-player-name">${esc(r.riotId)}</span><br><small class="kp-muted">인식 ${r.confidence}%</small></td><td><select name="agent-${i}" class="kp-stat-input" aria-label="${esc(r.riotId)} 요원">${AGENTS.map(a=>`<option ${a===r.agent?'selected':''}>${a}</option>`).join('')}</select></td>${['kills','deaths','assists'].map(k=>`<td><input name="${k}-${i}" type="number" min="0" max="99" required value="${esc(r[k])}" aria-label="${esc(r.riotId)} ${k}" class="kp-stat-input ${r.confidence<85&&!r.reviewed?'kp-review-cell':''}"></td>`).join('')}<td><input name="reviewed-${i}" type="checkbox" ${r.reviewed?'checked':''} required aria-label="${esc(r.riotId)} 기록 확인"></td></tr>`).join('')}</tbody></table></div><div class="kp-divider"></div><label class="kp-check"><input type="checkbox" required name="confirm">스크린샷과 주전 10명의 기록을 대조했습니다.</label><button type="submit" class="kp-button primary" style="margin-top:18px">운영진 검수 요청 →</button></article></form>${confirmedResults(submissions)}`;
}
function confirmedResults(submissions){return submissions.length?section('HISTORY','제출·검수 이력',`<div class="kp-panel">${submissions.map(s=>`<div class="kp-list-row"><div><h4>${esc(s.map)} · ${s.roundA} : ${s.roundB}</h4><small>${date(s.submittedAt)} ${esc(s.note)}</small></div>${badge(s.status)}</div>`).join('')}</div>`):'';}
function reviewPage(m,sub){return top('ADMIN / RESULT REVIEW',`${sub.map} · 결과 검수`,'제출된 스크린샷과 기록을 대조한 후 확정 또는 반려해 주세요.','',`match/${m.id}`)+`<div class="kp-result-layout"><article class="kp-panel kp-pad"><h3>제출 스크린샷</h3><img id="kp-review-evidence" class="kp-evidence" alt="제출된 경기 결과 스크린샷" ${demo&&sub.image?`src="${sub.image}"`:''}><p class="kp-meta">${date(sub.submittedAt)} · SET ${sub.mapIndex+1}</p><div class="kp-score-edit"><strong>${sub.roundA}</strong><span>:</span><strong>${sub.roundB}</strong></div></article><article class="kp-panel kp-pad"><div class="kp-table-scroll"><table class="kp-roster-table"><thead><tr><th>Riot ID</th><th>요원</th><th>K</th><th>D</th><th>A</th><th>인식</th></tr></thead><tbody>${sub.rows.map(r=>`<tr><td>${esc(r.riotId)}</td><td>${esc(r.agent)}</td><td>${r.kills}</td><td>${r.deaths}</td><td>${r.assists}</td><td>${r.confidence}%</td></tr>`).join('')}</tbody></table></div><label class="kp-field" style="margin-top:18px">검수 메모 / 반려 사유<textarea id="kp-review-note" maxlength="500" placeholder="잘못된 항목이 있으면 수정할 내용을 적어 주세요."></textarea></label><div class="kp-actions" style="margin-top:16px">${button('기록 확정','review-result',`data-id="${sub.id}" data-status="confirmed"`,'primary')}${button('반려 · 수정 요청','review-result',`data-id="${sub.id}" data-status="rejected"`,'danger')}</div></article></div>`;}
function recordsBody(filters={}){const data=metrics(state,filters);return `<div class="kp-tabs"><button class="${recordTab==='players'?'active':''}" data-action="record-tab" data-tab="players">선수 기록</button><button class="${recordTab==='teams'?'active':''}" data-action="record-tab" data-tab="teams">팀별 경기 이력</button></div>`+(recordTab==='players'?data.players.length?`<div class="kp-panel kp-table-scroll"><table class="kp-roster-table"><thead><tr><th>순위</th><th>선수 · Riot ID</th><th>팀</th><th>맵 수</th><th>K/D</th><th>KDA</th><th>K</th><th>D</th><th>A</th><th>요원 / 맵</th></tr></thead><tbody>${data.players.map((p,i)=>`<tr><td>${i+1}</td><td class="kp-player-name">${esc(p.riotId)}</td><td>${esc(teamName(p.teamId))}</td><td>${p.games}</td><td>${p.kd.toFixed(2)}</td><td>${p.kda.toFixed(2)}</td><td>${p.kills}</td><td>${p.deaths}</td><td>${p.assists}</td><td>${esc(Object.keys(p.agents).join(', '))}<br><small>${esc(Object.keys(p.maps).join(', '))}</small></td></tr>`).join('')}</tbody></table></div>`:empty('확정된 선수 기록이 없습니다.','운영진이 결과를 확정한 경기만 집계합니다.'):data.teams.length?`<div class="kp-grid two">${data.teams.map(p=>`<article class="kp-panel"><div class="kp-card-head"><h3>${esc(teamName(p.id))}</h3><span>${p.wins}승 ${p.losses}패</span></div>${p.matches.map(mid=>{const m=match(mid);return `<div class="kp-list-row"><div><h4>${esc(m.rosterA?.name)} ${m.scoreA} : ${m.scoreB} ${esc(m.rosterB?.name)}</h4><small>${date(m.startsAt,true)}</small></div>${go('경기',`match/${mid}`,'small')}</div>`;}).join('')}</article>`).join('')}</div>`:empty('확정된 팀 경기 이력이 없습니다.','종료된 대회의 팀별 승패를 이곳에서 확인할 수 있습니다.'));}
function selectFilter(name,label,options){return `<label class="kp-field">${label}<select data-record-filter="${name}"><option value="">전체</option>${options.map(([v,l])=>`<option value="${esc(v)}" ${recordFilters[name]===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function recordsPage(){return top('STATS & RANKINGS','선수·팀 기록실','운영진이 확정한 세트 기록만 집계합니다. KDA = (킬 + 어시스트) / 데스 · 0데스는 분모 1로 표시합니다.')+`<div class="kp-filters">${selectFilter('season','시즌',[...new Set(state.tournaments.map(t=>t.season))].map(s=>[s,s]))}${selectFilter('tournamentId','대회',state.tournaments.map(t=>[t.id,t.name]))}${selectFilter('teamId','팀',state.teams.map(t=>[t.id,t.name]))}${selectFilter('agent','요원',AGENTS.map(a=>[a,a]))}${selectFilter('map','맵',MAPS.map(m=>[m.name,m.name]))}</div>`+recordsBody(recordFilters);}
function hallPage(){return top('HALL OF FAME','기록은, 다음 무대로 이어진다.','시즌 우승 팀·MVP·최종 순위를 보존하고 WINTER·SUMMER 입상 팀을 FINAL 시드권과 연결합니다.')+(state.hall.length?`<div class="kp-grid three">${state.hall.slice().reverse().map(h=>`<article class="kp-panel kp-hall-card"><span class="kp-eyebrow">${esc(h.season)} / CHAMPIONS</span><h3>${esc(h.rankings[0]?.teamName)}</h3><span class="kp-badge gold">MVP · ${esc(h.mvp?.riotId)}</span><ol>${h.rankings.map(r=>`<li class="${r.rank<=h.seedSlots?'kp-rank':''}"><span>${r.rank}. ${esc(r.teamName)}</span><span>${r.rank<=h.seedSlots&&h.kind!=='FINAL'?'FINAL 시드권':'입상'}</span></li>`).join('')}</ol></article>`).join('')}</div>`:empty('새로운 챔피언을 기다립니다.','대회가 종료되면 운영진이 최종 순위와 MVP를 확정합니다.'));}
function adminPage(){if(!admin())return top('STAFF ONLY','운영진 관리실','승인된 운영진 계정으로만 접근할 수 있습니다.')+loginRequired(true);const t=tour(adminTournament)||state.tournaments[0];adminTournament=t?.id||'';const tid=t?.id;const pending=state.applications.filter(a=>a.status==='pending'&&(!tid||a.tournamentId===tid));const reviews=state.submissions.filter(s=>s.status==='pending'&&(!tid||match(s.matchId)?.tournamentId===tid));const today=state.matches.filter(m=>m.tournamentId===tid&&!['waiting','cancelled','finished'].includes(m.status));return top('KOV OPERATIONS','운영진 관리실','참가 승인부터 결과 검수, 일정과 시즌 마감까지 한 화면에서 처리합니다.',button('＋ 대회 등록','new-tournament','','primary'))+`<div class="kp-filters"><label class="kp-field">관리 대회<select id="kp-admin-tournament">${state.tournaments.map(t=>`<option value="${t.id}" ${t.id===tid?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label>${t?button('대회 설정','edit-tournament',`data-tid="${tid}"`)+go('대진표 관리',`bracket/${tid}`)+button('대회 종료·순위 확정','finalize',`data-tid="${tid}"`):''}</div><div class="kp-grid four">${[['승인 대기 팀',pending.length],['예정·진행 경기',today.length],['결과 검수 대기',reviews.length],['알림 전송 대기',state.notifications.filter(n=>n.status==='pending').length]].map(([l,v])=>`<article class="kp-panel kp-summary-stat"><small>${l}</small><strong>${v.toString().padStart(2,'0')}</strong></article>`).join('')}</div>${section('01','참가 팀 승인',pending.length?`<div class="kp-panel">${pending.map(a=>`<div class="kp-list-row"><div class="kp-team-line">${logo(a.snapshot)}<div><strong>${esc(a.snapshot.name)}</strong><br><small>주장 ${esc(a.snapshot.captainName)} · ${a.snapshot.players.length}인 · ${date(a.submittedAt,true)}</small></div></div><div class="kp-actions">${button('명단 검토','roster',`data-id="${a.id}"`,'small')}${button('승인','approve-application',`data-id="${a.id}" data-status="approved"`,'primary small')}${button('반려','approve-application',`data-id="${a.id}" data-status="rejected"`,'danger small')}</div></div>`).join('')}</div>`:empty('승인 대기 팀이 없습니다.','새로운 참가 신청이 도착하면 표시됩니다.'))}${section('02','결과 검수',reviews.length?`<div class="kp-panel">${reviews.map(sub=>{const m=match(sub.matchId);return `<div class="kp-list-row"><div><h4>${esc(m.rosterA.name)} vs ${esc(m.rosterB.name)} · SET ${sub.mapIndex+1}</h4><small>${esc(sub.map)} · ${sub.roundA}:${sub.roundB} · ${date(sub.submittedAt,true)}</small></div>${go('이미지·기록 검수 →',`result/${m.id}`,'primary small')}</div>`;}).join('')}</div>`:empty('검수 대기 결과가 없습니다.','주장이 제출한 결과만 검수 대기 목록에 표시됩니다.'))}${section('03','경기 일정 · 준비 현황',listMatches(today))}${section('04','Discord 경기 알림',`<div class="kp-note">${demo?'체험 모드에서는 Discord로 메시지를 전송하지 않습니다.':webhookReady?'지정 웹훅으로만 알림을 보냅니다. 전송 버튼으로 내용을 확인하고 발송해 주세요.':'KOV_DISCORD_WEBHOOK_URL 연결 후 지정 채널로 전송할 수 있습니다.'} 일정 변경·밴픽 시작·확정 결과를 알림 대기열에 보관합니다.</div><div class="kp-panel" style="margin-top:14px">${state.notifications.slice().reverse().slice(0,15).map(n=>`<div class="kp-list-row"><div><h4>${esc(n.title)}</h4><small>${esc(match(n.matchId)?.rosterA?.name||'')} vs ${esc(match(n.matchId)?.rosterB?.name||'')} · ${date(n.at,true)}</small></div><div class="kp-actions">${badge(n.status)}${n.status==='pending'||n.status==='failed'?button('내용 확인·전송','send-notification',`data-id="${n.id}"`,'small'):''}</div></div>`).join('')||'<div class="kp-empty">알림 대기열이 비어 있습니다.</div>'}</div>`)}${section('05','최근 운영 이력',`<div class="kp-panel">${state.audit.slice(-10).reverse().map(a=>`<div class="kp-list-row"><span class="kp-meta">${esc(a.type)} · ${esc(a.name)}</span><small>${date(a.at,true)}</small></div>`).join('')}</div>`)}`;}
function loginRequired(staff=false){return empty(staff?'운영진 권한이 필요합니다.':'Discord 로그인이 필요합니다.',staff?'igyeongsig_ 계정은 서버에서 Discord 계정을 검증한 뒤 운영진 권한을 부여합니다.':'로그인한 팀 주장은 신청·체크인·밴픽·결과 제출을 진행할 수 있습니다.',demo?'<span class="kp-meta">상단 역할에서 운영진 또는 주장을 선택해 주세요.</span>':button('Discord 로그인','login','','primary'));}
function notFound(){return empty('요청한 대회 또는 경기를 찾을 수 없습니다.','대회 메인에서 다시 선택해 주세요.',go('대회 메인','tournaments'));}

function render(){
  let content='';try{switch(route[0]){case 'tournaments':content=tournamentMain();break;case 'tournament':content=tournamentDetail(route[1]);break;case 'apply':content=applicationPage(route[1]);break;case 'bracket':content=bracketPage(route[1]);break;case 'match':content=matchPage(route[1]);break;case 'veto':content=vetoPage(route[1]);break;case 'result':content=resultPage(route[1]);break;case 'records':content=recordsPage();break;case 'hall':content=hallPage();break;case 'admin':content=adminPage();break;default:content=notFound();}}catch(error){content=empty('화면을 불러오지 못했습니다.',error.message,go('대회 메인','tournaments'));}
  app.innerHTML=statusBar()+routeNav()+content+`<footer class="kp-footer"><strong>KOV <span>COMPETITIVE COMMUNITY</span></strong><span>PLAY. COMPETE. PROVE.</span></footer>`;
  document.querySelectorAll('aside .nav-item').forEach(b=>{b.title=b.textContent.trim();b.setAttribute('aria-label',b.textContent.trim());});
  const activeNav=document.querySelector(`[data-kov-nav="${route[0]}"]`);if($('#page-home').classList.contains('active')){document.querySelectorAll('aside .nav-item').forEach(b=>b.classList.remove('active'));(activeNav||document.querySelector('[aria-label="KOV 홈"]'))?.classList.add('active');}
  if(route[0]==='result'&&admin()){const sub=state.submissions.find(s=>s.matchId===route[1]&&s.status==='pending');if(sub&&!demo)loadEvidence(sub);}
  updateTimer();
}
window.openKov=path=>{modal.close();const next=path.split('/');if(next[0]!=='result'||next[1]!==route[1])resultDraft=null;route=next;const hash='#kov/'+next.map(encodeURIComponent).join('/');if(location.hash!==hash)history.pushState(null,'',hash);window.goPage('home',document.querySelector('[aria-label="KOV 홈"]'));render();};
window.addEventListener('popstate',()=>{if(location.hash.startsWith('#kov/')){route=location.hash.slice(5).split('/').map(decodeURIComponent);window.goPage('home');render();}});
function demoActor(id){if(id==='demo-admin')return {id,name:'운영진 체험',isAdmin:true};const team=state.teams.find(t=>t.captainId===id);return {id,name:team?team.name+' 주장':'관람자',isAdmin:false};}
function loadDemo(reset=false){try{state=reset?demoState():JSON.parse(readLocal('kov-demo-v2')||'null')||demoState();if(state.schema!==2)state=demoState();}catch{state=demoState();}actor=demoActor(readLocal('kov-demo-role')||'demo-admin');storageReady=false;loading=false;}
async function fetchState(force=false){if(demo)return;try{const token=readLocal('discordToken');const response=await fetch('/api/kov',{headers:token?{Authorization:'Bearer '+token}:{},cache:'no-store'});const data=await responseJson(response);if(!response.ok)throw Error(data.error||'대회 서버 응답 오류');const changed=state.revision!==data.state.revision||loading||force;state=data.state;actor=data.actor;storageReady=data.storageReady;webhookReady=data.webhookReady;loading=false;if(changed&&!$('#kp-result-form')&&!modal.open)render();}catch(error){loading=false;if(force)toast(error.message);if(!state.tournaments.length)render();}}
async function command(type,payload){if(busy)throw Error('요청 처리 중입니다.');busy=true;try{if(demo){if(type==='sendNotification'){toast('체험 모드에서는 Discord로 전송하지 않습니다.');return {};}const evidence=payload.image;const commandPayload={...payload};if(type==='submitResult'){commandPayload.evidenceId='demo-evidence-'+crypto.randomUUID();delete commandPayload.image;}const result=applyCommand(state,{type,payload:commandPayload},actor);state=result.state;if(type==='submitResult')state.submissions.at(-1).image=evidence;const serialized=JSON.stringify(state);if(!writeLocal('kov-demo-v2',serialized))throw Error('체험 저장 공간이 부족합니다. 이미지를 줄이거나 체험 데이터를 초기화해 주세요.');render();return result.output;}
    const token=readLocal('discordToken');if(!token)throw Error('Discord 로그인이 필요합니다.');const response=await fetch('/api/kov',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({type,payload})});const data=await responseJson(response);if(!response.ok){if(response.status===409)await fetchState();throw Error(data.error||'요청 실패');}if(data.state){state=data.state;actor=data.actor;storageReady=true;}else await fetchState();render();return data.output||{};
  }finally{busy=false;}}
async function loadEvidence(sub){try{const response=await fetch('/api/kov?evidence='+encodeURIComponent(sub.evidenceId),{headers:{Authorization:'Bearer '+readLocal('discordToken')}});const data=await responseJson(response);if(!response.ok)throw Error(data.error);const image=$('#kp-review-evidence');if(image)image.src=data.image;}catch(error){toast(error.message);}}
function updateTimer(){const el=$('[data-deadline]');if(!el)return;const deadline=Number(el.dataset.deadline);if(!deadline){el.textContent='✓';return;}const seconds=Math.max(0,Math.ceil((deadline-Date.now())/1000));el.textContent=seconds+'s';el.classList.toggle('kp-timer-expired',seconds===0);}

function teamEditor(id){if(!actor)return toast('먼저 Discord로 로그인해 주세요.');const team=state.teams.find(t=>t.id===id);const players=team?.players||Array.from({length:7},(_,i)=>({name:'',riotId:'',discordId:i===0?actor.id:'',slot:i<5?'starter':'sub'}));showModal('내 팀 등록 · 명단 관리',`<form id="kp-team-form" class="kp-form" data-id="${esc(id||'')}"><div class="kp-form-grid"><label class="kp-field">팀 이름<input name="name" required maxlength="40" value="${esc(team?.name)}" placeholder="예: TEAM ECLIPSE"></label><label class="kp-field">팀 로고 주소 · 선택<input name="logoUrl" type="url" value="${esc(team?.logoUrl)}" placeholder="https://…"></label></div><div class="kp-note">주장은 로그인 계정으로 지정됩니다. 본인 선수 행에 Discord 사용자 ID <strong>${esc(actor.id)}</strong>를 입력해 주세요. 주전 5명은 필수이며 후보 2명은 선택입니다. 기존 대회에 제출된 명단은 변경되지 않습니다.</div><div class="kp-roster-edit"><div class="kp-roster-labels"><span>구분</span><span>선수 이름</span><span>Riot ID</span><span>Discord ID · 선택</span></div>${Array.from({length:7},(_,i)=>{const p=players[i]||{slot:'sub'};return `<div data-team-player="${i}" data-player-id="${esc(p.id||'')}"><select name="slot-${i}" aria-label="선수 ${i+1} 구분"><option value="starter" ${p.slot==='starter'?'selected':''}>주전</option><option value="sub" ${p.slot==='sub'?'selected':''}>후보</option></select><input name="name-${i}" aria-label="선수 ${i+1} 이름" placeholder="선수 이름" maxlength="30" value="${esc(p.name)}" ${i<5?'required':''}><input name="riotId-${i}" aria-label="선수 ${i+1} Riot ID" placeholder="이름#태그" value="${esc(p.riotId)}" maxlength="48" ${i<5?'required':''}><input name="discordId-${i}" aria-label="선수 ${i+1} Discord ID" placeholder="숫자 사용자 ID" value="${esc(p.discordId)}" maxlength="25"></div>`;}).join('')}</div><button class="kp-button primary" type="submit">팀 명단 저장</button></form>`);}
const localDate=value=>{const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
function tournamentEditor(tid){if(!admin())return;const t=tour(tid)||{year:new Date().getFullYear(),kind:'WINTER',bestOf:3,capacity:8,seedSlots:2,status:'registration'};showModal(tid?'대회 설정':'새 대회 등록',`<form id="kp-tournament-form" class="kp-form" data-id="${esc(tid||'')}"><div class="kp-form-grid"><label class="kp-field wide">대회 이름<input name="name" required maxlength="80" value="${esc(t.name)}"></label><label class="kp-field">연도<input name="year" type="number" min="2020" max="2100" value="${t.year}" required></label><label class="kp-field">시즌<select name="kind">${['WINTER','SUMMER','FINAL'].map(k=>`<option ${k===t.kind?'selected':''}>${k}</option>`).join('')}</select></label><label class="kp-field">대회 시작<input name="startAt" type="datetime-local" value="${localDate(t.startAt)}" required></label><label class="kp-field">대회 종료<input name="endAt" type="datetime-local" value="${localDate(t.endAt)}" required></label><label class="kp-field">접수 마감<input name="deadline" type="datetime-local" value="${localDate(t.deadline)}" required></label><label class="kp-field">참가 규모<input name="capacity" type="number" min="8" max="32" step="8" value="${t.capacity}" required></label><label class="kp-field">BO 형식<select name="bestOf">${[1,3,5].map(n=>`<option value="${n}" ${n===t.bestOf?'selected':''}>BO${n}</option>`).join('')}</select></label><label class="kp-field">상태<select name="status">${['draft','registration','ongoing'].map(v=>`<option value="${v}" ${t.status===v?'selected':''}>${names[v]}</option>`).join('')}</select></label><label class="kp-field">총 상금<input name="prize" value="${esc(t.prize)}" maxlength="100"></label><label class="kp-field">FINAL 시드권 · 상위 팀 수<input name="seedSlots" type="number" min="1" max="4" value="${t.seedSlots}"></label><label class="kp-field">포스터 HTTPS 주소<input name="posterUrl" type="url" value="${esc(t.posterUrl)}"></label><label class="kp-field">방송 HTTPS 주소<input name="broadcastUrl" type="url" value="${esc(t.broadcastUrl)}"></label><label class="kp-field wide">대회 소개<textarea name="description" maxlength="3000">${esc(t.description)}</textarea></label><label class="kp-field wide">대회 규정<textarea name="rules" maxlength="5000">${esc(t.rules)}</textarea></label></div><div class="kp-note">등록 시간은 현재 기기의 시간대 기준이며 화면에는 KST로 표시합니다. 맵 풀: ${MAPS.map(m=>m.name).join(' / ')}<br>스위스 3승·3패 종료 → 승패·BH·시드 순 상위 4팀 플레이오프 → 그랜드 파이널(필요 시 리셋)을 지원합니다.</div><button type="submit" class="kp-button primary">대회 저장</button></form>`);}

function collectResult(){if(!resultDraft||!$('#kp-result-form'))return;const form=$('#kp-result-form');const data=new FormData(form);resultDraft.roundA=data.get('roundA');resultDraft.roundB=data.get('roundB');for(let i=0;i<resultDraft.rows.length;i++){const r=resultDraft.rows[i];r.agent=data.get('agent-'+i);for(const k of ['kills','deaths','assists'])r[k]=data.get(k+'-'+i);r.reviewed=data.get('reviewed-'+i)==='on';}resultDraft.raw=$('#kp-ocr-text')?.value||resultDraft.raw;}
async function resizeEvidence(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('8MB 이하 PNG·JPEG·WebP를 선택해 주세요.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let quality=.9,image;do{image=canvas.toDataURL('image/jpeg',quality);quality-=.1;}while(image.length>850000&&quality>.25);if(image.length>850000)throw Error('이미지가 너무 큽니다. 스코어보드 부분만 잘라서 업로드해 주세요.');return image;}
let ocrLoader;
function loadOcr(){if(window.Tesseract)return Promise.resolve();if(!ocrLoader)ocrLoader=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';script.onload=resolve;script.onerror=()=>{ocrLoader=null;reject(Error('OCR 모듈을 불러오지 못했습니다. 네트워크를 확인하거나 직접 기록을 입력해 주세요.'));};document.head.appendChild(script);});return ocrLoader;}
async function runOcr(){if(!resultDraft?.image||ocrBusy)return;collectResult();ocrBusy=true;const target=resultDraft;let worker;try{target.progress='OCR 언어 데이터를 준비하고 있습니다…';render();await loadOcr();worker=await window.Tesseract.createWorker('eng+kor',1,{logger:m=>{if(resultDraft===target){target.progress=`${m.status} ${Math.round((m.progress||0)*100)}%`;const status=$('#kp-ocr-progress');if(status)status.textContent=target.progress;}}});const result=await worker.recognize(target.image);if(resultDraft!==target)return;target.raw=result.data.text;target.rows=parseScoreboard(target.raw,target.rows);target.progress='인식 완료 · 숫자와 요원을 직접 확인하고 선수별 확인을 체크해 주세요.';toast('OCR 인식이 완료됐습니다. 불확실한 칸을 확인해 주세요.');}catch(error){target.progress=error.message;toast(error.message);}finally{if(worker)await worker.terminate();ocrBusy=false;if(resultDraft===target)render();}}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||(!app.contains(b)&&!modal.contains(b)))return;const a=b.dataset.action;if(b.disabled)return;try{switch(a){
  case 'route':window.openKov(b.dataset.path);break;
  case 'close-modal':modal.close();break;
  case 'login':window.discordLogin();break;
  case 'enter-demo':demo=true;writeLocal('kov-demo-active','1');loadDemo();window.openKov('tournaments');toast('체험 모드입니다. 실제 서버·Discord에는 변경을 보내지 않습니다.');break;
  case 'exit-demo':demo=false;writeLocal('kov-demo-active','0');state=initialState();actor=null;route=['tournaments'];loading=true;render();await fetchState(true);window.openKov('tournaments');break;
  case 'reset-demo':showModal('체험 데이터 초기화','<p class="kp-desc">이 브라우저의 체험 데이터만 초기 상태로 되돌립니다. 실서비스 데이터에는 영향을 주지 않습니다.</p>'+button('체험 초기화','confirm-reset','','primary'));break;
  case 'confirm-reset':loadDemo(true);writeLocal('kov-demo-v2',JSON.stringify(state));modal.close();window.openKov('tournaments');break;
  case 'detail-tab':detailTab=b.dataset.tab;render();break;
  case 'record-tab':recordTab=b.dataset.tab;render();break;
  case 'edit-team':teamEditor(b.dataset.id);break;
  case 'new-tournament':tournamentEditor();break;
  case 'edit-tournament':tournamentEditor(b.dataset.tid);break;
  case 'roster':{const item=state.applications.find(x=>x.id===b.dataset.id);showModal(item.snapshot.name+' · 참가 명단',`<p class="kp-meta">${date(item.submittedAt)} 신청 시점에 보관된 명단입니다.</p>${rosterTable(item.snapshot)}`);break;}
  case 'apply':if(!$('#kp-roster-consent')?.checked)throw Error('명단과 규정을 확인한 뒤 체크해 주세요.');await command('apply',{tournamentId:b.dataset.tid,teamId:b.dataset.team});toast('참가 신청을 제출했습니다. 운영진 승인을 기다려 주세요.');break;
  case 'approve-application':{const id=b.dataset.id,status=b.dataset.status;showModal(status==='approved'?'참가 승인':'참가 신청 반려',`<form id="kp-application-review" class="kp-form" data-id="${id}" data-status="${status}"><label class="kp-field">검토 메모${status==='rejected'?' · 필수':''}<textarea name="note" maxlength="300" ${status==='rejected'?'required':''}></textarea></label><button class="kp-button ${status==='approved'?'primary':'danger'}" type="submit">${status==='approved'?'명단 확인 후 승인':'반려 확정'}</button></form>`);break;}
  case 'generate-swiss':case 'generate-playoffs':{const type=a==='generate-swiss'?'generateSwiss':'generatePlayoffs';showModal(type==='generateSwiss'?'스위스 다음 라운드 생성':'4강 플레이오프 생성',`<p class="kp-desc">현재 확정된 승패와 시드를 기준으로 대진을 생성합니다. 생성 후 경기별 시간을 조정할 수 있습니다.</p>${button('대진 생성','confirm-generate',`data-type="${type}" data-tid="${b.dataset.tid}"`,'primary')}`);break;}
  case 'confirm-generate':await command(b.dataset.type,{tournamentId:b.dataset.tid});modal.close();toast('대진을 생성했습니다.');break;
  case 'checkin':case 'ready':await command(a,{matchId:b.dataset.mid});toast(a==='checkin'?'체크인했습니다.':'경기 준비 상태를 변경했습니다.');break;
  case 'start-veto':await command('startVeto',{matchId:b.dataset.mid});toast('밴픽을 시작했습니다.');break;
  case 'lineup':{const m=match(b.dataset.mid),side=mySide(m);if(!side)throw Error('주장만 출전 명단을 선택할 수 있습니다.');const r=side==='A'?m.rosterA:m.rosterB;const active=activePlayers(m,side).map(p=>p.id);showModal('출전 명단 선택 · 5명',`<form id="kp-lineup-form" class="kp-form" data-mid="${m.id}"><p class="kp-note">대회 참가 당시 명단에 등록한 주전·후보 중 5명을 선택합니다. 준비 완료 후에는 바꿀 수 없습니다.</p>${r.players.map(p=>`<label class="kp-check"><input type="checkbox" name="playerIds" value="${p.id}" ${active.includes(p.id)?'checked':''}>${esc(p.name)} · ${esc(p.riotId)} · ${p.slot==='sub'?'후보':'주전'}</label>`).join('')}<button type="submit" class="kp-button primary">출전 명단 확정</button></form>`);break;}
  case 'veto':await command('veto',{matchId:b.dataset.mid,value:b.dataset.value});break;
  case 'veto-timeout':await command('vetoTimeout',{matchId:b.dataset.mid});toast('시간 초과 선택을 처리했습니다.');break;
  case 'schedule':{const m=match(b.dataset.mid);showModal('경기 일정·방송 수정',`<form id="kp-schedule-form" class="kp-form" data-mid="${m.id}"><label class="kp-field">경기 시작 시간<input name="startsAt" type="datetime-local" required value="${localDate(m.startsAt)}"></label><label class="kp-field">방송 HTTPS 주소<input name="broadcastUrl" type="url" value="${esc(m.broadcastUrl)}"></label><button class="kp-button primary" type="submit">일정 저장 · 알림 대기열 추가</button></form>`);break;}
  case 'ocr':await runOcr();break;
  case 'parse-ocr':collectResult();resultDraft.rows=parseScoreboard(resultDraft.raw,resultDraft.rows);render();break;
  case 'review-result':{const status=b.dataset.status;showModal(status==='confirmed'?'결과 확정 확인':'결과 반려 확인',`<form id="kp-result-review" class="kp-form" data-id="${b.dataset.id}" data-status="${status}"><p class="kp-note">${status==='confirmed'?'확정하면 세트 스코어·선수 기록에 반영되며 승리 조건 충족 시 다음 대진으로 자동 진출합니다.':'반려하면 주장에게 수정 사유가 표시되고 해당 세트를 다시 제출할 수 있습니다.'}</p><label class="kp-field">검수 메모<textarea name="note" maxlength="500" ${status==='rejected'?'required':''}>${esc($('#kp-review-note')?.value||'')}</textarea></label><button type="submit" class="kp-button ${status==='confirmed'?'primary':'danger'}">${status==='confirmed'?'확정':'반려'}</button></form>`);break;}
  case 'finalize':{const players=metrics(state,{tournamentId:b.dataset.tid}).players;showModal('대회 종료 · 최종 순위 확정',`<form id="kp-finalize-form" class="kp-form" data-tid="${b.dataset.tid}"><div class="kp-note">그랜드 파이널 결과로 최종 1~4위를 보관하고, 지정된 상위 팀의 FINAL 시드권을 연결합니다. 대회 종료 후에는 대회 설정과 명단 승인을 변경할 수 없습니다.</div><label class="kp-field">대회 MVP<select name="mvpId"><option value="">KDA·킬 기준 자동 선정</option>${players.map(p=>`<option value="${p.id}">${esc(p.riotId)}</option>`).join('')}</select></label><button class="kp-button primary" type="submit">최종 순위·MVP 확정</button></form>`);break;}
  case 'send-notification':{const n=state.notifications.find(x=>x.id===b.dataset.id),m=match(n.matchId);showModal('Discord 알림 전송 확인',`<p class="kp-rules">${esc(n.title)}\n${esc(m?.rosterA?.name)} vs ${esc(m?.rosterB?.name)}\n${date(m?.startsAt)}\n경기 페이지 링크가 함께 전송됩니다.</p><p class="kp-note">${demo?'체험 모드: 실제 메시지를 전송하지 않습니다.':'연결된 공식 웹훅 채널로 전송합니다. 이전 실패 건은 중복 수신 여부를 먼저 확인해 주세요.'}</p>${button('지정 채널로 전송','confirm-send',`data-id="${n.id}"`,'primary')}`);break;}
  case 'confirm-send':await command('sendNotification',{id:b.dataset.id});modal.close();if(!demo)toast('Discord에 전송했습니다.');break;
}}catch(error){toast(error.message);}});

document.addEventListener('change',async e=>{try{
  if(e.target.id==='kp-demo-role'){actor=demoActor(e.target.value);writeLocal('kov-demo-role',actor.id);render();}
  if(e.target.id==='kp-application-team'){selectedTeam=e.target.value;render();}
  if(e.target.id==='kp-admin-tournament'){adminTournament=e.target.value;render();}
  if(e.target.dataset.recordFilter){recordFilters[e.target.dataset.recordFilter]=e.target.value;render();}
  if(e.target.id==='kp-result-image'&&e.target.files[0]){collectResult();resultDraft.image=await resizeEvidence(e.target.files[0]);render();}
  if(e.target.closest('#kp-result-form'))collectResult();
}catch(error){toast(error.message);}});
document.addEventListener('submit',async e=>{if(!e.target.id?.startsWith('kp-'))return;e.preventDefault();const form=e.target,submit=form.querySelector('[type=submit]');submit.disabled=true;try{const d=new FormData(form);switch(form.id){
  case 'kp-team-form':{const players=[...form.querySelectorAll('[data-team-player]')].map(row=>{const i=row.dataset.teamPlayer;return {id:row.dataset.playerId,name:d.get('name-'+i),riotId:d.get('riotId-'+i),discordId:d.get('discordId-'+i),slot:d.get('slot-'+i)};}).filter(p=>p.name||p.riotId);const output=await command('saveTeam',{id:form.dataset.id||undefined,name:d.get('name'),logoUrl:d.get('logoUrl'),players});selectedTeam=output.teamId;modal.close();render();toast('팀 명단을 저장했습니다.');break;}
  case 'kp-tournament-form':{const payload=Object.fromEntries(d);payload.id=form.dataset.id||undefined;for(const k of ['startAt','endAt','deadline'])payload[k]=new Date(payload[k]).toISOString();payload.mapPool=MAPS.map(m=>m.name);const output=await command('saveTournament',payload);modal.close();window.openKov('tournament/'+output.tournamentId);toast('대회를 저장했습니다.');break;}
  case 'kp-application-review':await command('reviewApplication',{id:form.dataset.id,status:form.dataset.status,note:d.get('note')});modal.close();render();toast('신청 검토를 완료했습니다.');break;
  case 'kp-schedule-form':await command('schedule',{matchId:form.dataset.mid,startsAt:new Date(d.get('startsAt')).toISOString(),broadcastUrl:d.get('broadcastUrl')});modal.close();render();toast('일정과 알림 대기열을 저장했습니다.');break;
  case 'kp-result-form':collectResult();if(!resultDraft.image)throw Error('결과 스크린샷을 첨부해 주세요.');await command('submitResult',{...resultDraft});resultDraft=null;render();toast('운영진에게 결과 검수를 요청했습니다.');break;
  case 'kp-lineup-form':await command('setLineup',{matchId:form.dataset.mid,playerIds:d.getAll('playerIds')});modal.close();render();toast('이번 경기 출전 명단을 저장했습니다.');break;
  case 'kp-result-review':await command('reviewResult',{id:form.dataset.id,status:form.dataset.status,note:d.get('note')});modal.close();render();toast(form.dataset.status==='confirmed'?'결과가 공식 기록에 반영되었습니다.':'결과를 반려했습니다.');break;
  case 'kp-finalize-form':await command('finalizeTournament',{tournamentId:form.dataset.tid,mvpId:d.get('mvpId')});modal.close();window.openKov('hall');toast('최종 순위와 MVP를 보관했습니다.');break;
}}catch(error){toast(error.message);}finally{submit.disabled=false;}});

window.addEventListener('message',e=>{if(e.data?.type==='DISCORD_LOGIN_SUCCESS')setTimeout(()=>fetchState(true),150);});
window.addEventListener('storage',e=>{if(demo&&e.key==='kov-demo-v2'){try{state=JSON.parse(e.newValue);render();}catch{}}else if(e.key==='discordToken')fetchState(true);});
const sprite=document.querySelector('svg symbol')?.parentElement;if(sprite&&!$('#ic-home'))sprite.insertAdjacentHTML('beforeend','<symbol id="ic-home" viewBox="0 0 24 24" fill="currentColor"><path d="M12 3 2 11h3v10h5v-6h4v6h5V11h3L12 3z"/></symbol>');
if(demo)loadDemo();render();if(!demo)fetchState(true);setInterval(updateTimer,250);setInterval(()=>{if(document.visibilityState==='visible')fetchState();},4000);
